import{_ as t,o as d,c as o,ae as r}from"./chunks/framework.C4zpkcTP.js";const p=JSON.parse('{"title":"Results","description":"Property reference for RedirectPayment, FormPayment, QrPayment and AppPayment, the result classes returned when a payment is started.","frontmatter":{"title":"Results","description":"Property reference for RedirectPayment, FormPayment, QrPayment and AppPayment, the result classes returned when a payment is started."},"headers":[],"relativePath":"php-myanmar-payments/references/results.md","filePath":"php-myanmar-payments/references/results.md"}'),a={name:"php-myanmar-payments/references/results.md"};function c(n,e,s,i,l,m){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="results" tabindex="-1">Results <a class="header-anchor" href="#results" aria-label="Permalink to &quot;Results&quot;">​</a></h1><p>Starting a payment returns one of four final classes in <code>Laranex\\PhpMyanmarPayments\\Results</code>, with read-only properties. Each implements <code>PaymentResult</code>, whose <code>flow()</code> returns a <code>PaymentFlow</code>, so a <code>match</code> or <code>instanceof</code> check tells them apart. Properties a gateway did not provide are <code>null</code>.</p><h2 id="redirectpayment" tabindex="-1">RedirectPayment <a class="header-anchor" href="#redirectpayment" aria-label="Permalink to &quot;RedirectPayment&quot;">​</a></h2><p>Returned by <code>$kbz-&gt;pwa()</code> and <code>$wave-&gt;initiate()</code>.</p><table tabindex="0"><thead><tr><th>Property / Method</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>flow()</code></td><td><code>PaymentFlow</code></td><td><code>PaymentFlow::Redirect</code></td></tr><tr><td><code>orderId</code></td><td><code>string</code></td><td>Your order ID, as sent to the gateway</td></tr><tr><td><code>url</code></td><td><code>string</code></td><td>The gateway page to redirect the customer to</td></tr><tr><td><code>gatewayReference</code></td><td><code>?string</code></td><td>The gateway&#39;s ID for this attempt (KBZ <code>prepay_id</code>, Wave <code>transaction_id</code>)</td></tr><tr><td><code>raw</code></td><td><code>array</code></td><td>The gateway&#39;s response, for logging</td></tr></tbody></table><h2 id="formpayment" tabindex="-1">FormPayment <a class="header-anchor" href="#formpayment" aria-label="Permalink to &quot;FormPayment&quot;">​</a></h2><p>Returned by <code>$aya-&gt;initiate()</code> and <code>$cs-&gt;initiate()</code>.</p><table tabindex="0"><thead><tr><th>Property / Method</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>flow()</code></td><td><code>PaymentFlow</code></td><td><code>PaymentFlow::Form</code></td></tr><tr><td><code>orderId</code></td><td><code>string</code></td><td>Your order ID</td></tr><tr><td><code>action</code></td><td><code>string</code></td><td>The gateway URL the form posts to</td></tr><tr><td><code>fields</code></td><td><code>array&lt;string, string&gt;</code></td><td>The signed hidden fields, name =&gt; value, in order. Post them unchanged</td></tr><tr><td><code>enctype</code></td><td><code>string</code></td><td>The encoding the gateway expects; <code>application/x-www-form-urlencoded</code> unless the gateway needs another (AYA: <code>multipart/form-data</code>)</td></tr><tr><td><code>toHtml()</code></td><td><code>string</code></td><td>A complete, escaped page that submits the form on load</td></tr><tr><td><code>field($name)</code></td><td><code>?string</code></td><td>One field&#39;s value</td></tr><tr><td><code>values()</code></td><td><code>array&lt;string, string&gt;</code></td><td>The fields as an array</td></tr><tr><td><code>autoSubmitUrl</code></td><td><code>?string</code></td><td>Link to a page that renders the form. <code>null</code> unless set with <code>withAutoSubmitUrl()</code></td></tr><tr><td><code>withAutoSubmitUrl($url)</code></td><td><code>FormPayment</code></td><td>A copy with <code>autoSubmitUrl</code> set</td></tr></tbody></table><h2 id="qrpayment" tabindex="-1">QrPayment <a class="header-anchor" href="#qrpayment" aria-label="Permalink to &quot;QrPayment&quot;">​</a></h2><p>Returned by <code>$kbz-&gt;qr()</code>, <code>$yoma-&gt;initiate()</code> and <code>$yoma-&gt;renewQr()</code>.</p><table tabindex="0"><thead><tr><th>Property / Method</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>flow()</code></td><td><code>PaymentFlow</code></td><td><code>PaymentFlow::Qr</code></td></tr><tr><td><code>orderId</code></td><td><code>string</code></td><td>Your order ID</td></tr><tr><td><code>qrString</code></td><td><code>?string</code></td><td>A QR payload to encode yourself (KBZ Pay)</td></tr><tr><td><code>qrImage</code></td><td><code>?string</code></td><td>A base64 image to display as is (Yoma MMQR)</td></tr><tr><td><code>expiresAt</code></td><td><code>?DateTimeImmutable</code></td><td>When the QR stops being payable; <code>null</code> when the gateway sets no limit</td></tr><tr><td><code>reference</code></td><td><code>?string</code></td><td>The gateway&#39;s ID for this QR, used for status checks (Yoma <code>refLabel</code>, KBZ <code>prepay_id</code>)</td></tr><tr><td><code>raw</code></td><td><code>array</code></td><td>The gateway&#39;s response, for logging</td></tr><tr><td><code>qrImageDataUri($mimeType = &#39;image/png&#39;)</code></td><td><code>?string</code></td><td><code>qrImage</code> as a data URI. <code>null</code> when there is no image</td></tr></tbody></table><h2 id="apppayment" tabindex="-1">AppPayment <a class="header-anchor" href="#apppayment" aria-label="Permalink to &quot;AppPayment&quot;">​</a></h2><p>Returned by <code>$kbz-&gt;app()</code>. <code>$payment-&gt;toArray()</code> returns <code>orderId</code>, <code>orderInfo</code>, <code>sign</code> and <code>signType</code>, the names the KBZ Pay SDK uses.</p><table tabindex="0"><thead><tr><th>Property / Method</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>flow()</code></td><td><code>PaymentFlow</code></td><td><code>PaymentFlow::App</code></td></tr><tr><td><code>orderId</code></td><td><code>string</code></td><td>Your order ID</td></tr><tr><td><code>orderInfo</code></td><td><code>string</code></td><td>The signed order string the SDK expects</td></tr><tr><td><code>sign</code></td><td><code>string</code></td><td>The signature of <code>orderInfo</code></td></tr><tr><td><code>signType</code></td><td><code>string</code></td><td>The signature algorithm, <code>SHA256</code></td></tr><tr><td><code>raw</code></td><td><code>array</code></td><td>The gateway&#39;s response; left out of <code>toArray()</code></td></tr><tr><td><code>toArray()</code></td><td><code>array&lt;string, string&gt;</code></td><td><code>[&#39;orderId&#39;, &#39;orderInfo&#39;, &#39;sign&#39;, &#39;signType&#39;]</code>, the values your app needs</td></tr></tbody></table><h2 id="paymentflow" tabindex="-1">PaymentFlow <a class="header-anchor" href="#paymentflow" aria-label="Permalink to &quot;PaymentFlow&quot;">​</a></h2><p>A string-backed enum in <code>Laranex\\PhpMyanmarPayments\\Enums</code>, so <code>$payment-&gt;flow()-&gt;value</code> is <code>redirect</code>, <code>form</code>, <code>qr</code> or <code>app</code>.</p><table tabindex="0"><thead><tr><th>Case</th><th>Value</th><th>Class</th></tr></thead><tbody><tr><td><code>PaymentFlow::Redirect</code></td><td><code>redirect</code></td><td><code>RedirectPayment</code></td></tr><tr><td><code>PaymentFlow::Form</code></td><td><code>form</code></td><td><code>FormPayment</code></td></tr><tr><td><code>PaymentFlow::Qr</code></td><td><code>qr</code></td><td><code>QrPayment</code></td></tr><tr><td><code>PaymentFlow::App</code></td><td><code>app</code></td><td><code>AppPayment</code></td></tr></tbody></table><p><code>raw</code> values are decoded JSON: numbers keep their exact text as strings, never a <code>float</code>, so <code>json_encode($payment-&gt;raw)</code> logs them without rounding.</p><p>Every result class takes its properties as named constructor arguments, so you can build one in your own tests, e.g. <code>new RedirectPayment(orderId: &#39;ORDER_1&#39;, url: &#39;https://…&#39;)</code>.</p>',19)])])}const y=t(a,[["render",c]]);export{p as __pageData,y as default};
